WITH valid AS (SELECT id, store_id, quantity, last_restock, QUARTER(last_restock) AS last_restock_quarter FROM inventory WHERE last_restock >= DATE '2023-03-06'), cleaned AS (SELECT id, store_id, quantity, last_restock, last_restock_quarter, quantity * last_restock_quarter AS quantity_times_last_restock_quarter, ADD_MONTHS(last_restock, 6) AS last_restock_plus_months FROM valid WHERE last_restock >= DATE '2023-03-23'), latest AS (SELECT id, store_id, quantity, last_restock_plus_months FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY store_id ORDER BY last_restock_quarter NULLS FIRST, id) AS dedup_rank FROM cleaned) x WHERE dedup_rank = 1), ranked AS (SELECT * FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY store_id ORDER BY quantity DESC NULLS LAST, id) AS rn FROM latest) ranked WHERE rn = 1), with_windows AS (SELECT id, store_id, NTILE(10) OVER (PARTITION BY YEAR(last_restock_plus_months), store_id ORDER BY quantity, id) AS quantity_bucket, MAX(quantity) OVER (PARTITION BY store_id) AS store_id_max_quantity, LEAD(quantity, 1, 0) OVER (ORDER BY last_restock_plus_months, id) AS next_quantity FROM ranked WHERE rn >= 1) SELECT *, LAG(next_quantity) OVER w_ordered AS prev_next_quantity, LEAD(next_quantity) OVER w_ordered AS next_next_quantity, LEAD(quantity_bucket) OVER w_ordered AS next_quantity_bucket, ROW_NUMBER() OVER w_ordered AS seq_no, ROW_NUMBER() OVER (PARTITION BY store_id ORDER BY next_quantity, id) AS row_seq FROM with_windows WINDOW w_ordered AS (PARTITION BY store_id ORDER BY quantity_bucket, id)
